    [7607]={name="Sable Wand",quality=2,ilvl=22,reqLevel=15,sourceType="quest_reward",instructions="Reward from the quest 'Underground Assault'. Pick it over the other reward choices. Starts with Shoni the Shilent in Stormwind City. Objective: Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.",zone="The Deadmines",questName="Underground Assault",lore="Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help. Deep in the Deadmines is a functional goblin shredder."},
