    [17719]={name="Inventor's Focal Sword",quality=3,ilvl=53,reqLevel=48,sourceType="boss_drop",instructions="Drops from Tinkerer Gizlock.",zone="Maraudon",npc="Tinkerer Gizlock",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
